import { GoogleMap, Marker, LoadScript } from "@react-google-maps/api";

const mapContainerStyle = {
    width: "100%",
    height: "400px"
};

const MapComponent = ({ centralPoint, places }) => {
    const center = centralPoint || { lat: 37.7749, lng: -122.4194 }; // Default: San Francisco

    return (
        <LoadScript googleMapsApiKey={process.env.REACT_APP_GOOGLE_MAPS_API_KEY}>
            <GoogleMap mapContainerStyle={mapContainerStyle} center={center} zoom={12}>
                {centralPoint && <Marker position={centralPoint} label="📍 Meeting Spot" />}
                {places.map(place => (
                    <Marker key={place.place_id} position={{ lat: place.geometry.location.lat, lng: place.geometry.location.lng }} />
                ))}
            </GoogleMap>
        </LoadScript>
    );
};

export default MapComponent;
